_interv = [a for a in main_arms if '+v' in a or '-v' in a]
_post_cells = len(_interv) - len(quality['arms'])            # 選定の段で検べた二つの腕を除く（転記行 E と同じ数え方）
_qf_bases = (0.5, quality['base_min_floor'], quality['base_min'])   # 0.5 は裁定 D129 の前の下限（比べるために並べる）
T['measured']['quality_floor_multiplicity'] = dict(_rules.qf_multiplicity(T, _post_cells, bases=_qf_bases),
    note=('選定後の品質床が当たるセルで、帰無（腕と無操作の真の正答率が同じ）の一セルの発火率（`cell_at_*`）・%d セルで一つ以上落ちる確率（`any_at_*`・独立の近似）・'
          '真の低下を捕まえる確率（`power_at_*`）を、正答率ごとに**境目の規則どおり**（ちょうど閾値の差は不合格）に数えた（裁定 D137・`rules_B.qf_multiplicity`・転記行 E と同じ関数）。'
          '正答率は裁定 D129 の前の下限・手当ての下限（`base_min_floor`）・下限（`base_min`）。二標本は対の見方より保守側の上限である（`quality_floor.two_sample_note`）。'
          '前は手で打った数で、境目の規則と合わなかった（採否表 P391）') % _post_cells)
_td_bases = tuple(sorted({round(base_of(sc, b)['k'] / base_of(sc, b)['n'], 4) for sc in SC for b in ('O-Ncold', 'Onull')}))
T['measured']['td_specificity_null'] = dict(_rules.td_specificity_null(T, n=n_main, bases=_td_bases),
    bases_source='確証の族の土台（O-Ncold・Onull）の V′ の既測の率（場面ごと）',
    summary=('v と td の真の率が同じとき、Holm を掛ける前に一対比が決まった一方の向きに零を外す確率（上限・各腕 n=%d）: %s'
             % (n_main, '・'.join('基底 %s で %.4f' % (p_, r_) for p_, r_ in _rules.td_specificity_null(T, n=n_main, bases=_td_bases)['one_direction_before_holm'].items()))),
    bases=list(_td_bases),
    note=('裁定 D133 の規則の帰無の動作特性の**上限**——v と td の真の率が同じとき、両側 %g%% の区間が決まった一方の向きに零を外す確率（Holm を掛ける前・確証が立った前提）。'
          'Holm を掛ければ、これより小さい。前の規則（水準 `1 − alpha_upper`・向きを見ない）では、帰無で一対比の「書ける」が遥かに大きかった（採否表 P384）') % 95)
_hn = {}
for _sc, _arm in _rand_cells:
    _b = base_of(_sc, _base_arm(_arm))
    if _b.get('n'):
        _p = round(_b['k'] / _b['n'], 4)
        _hn.setdefault(_p, []).append('%s:%s' % (_sc, _arm))
_hns = [n_main // RANDOM['count'] + (1 if i < n_main % RANDOM['count'] else 0) for i in range(RANDOM['count'])]
_hrate = {p: round(_rules.homog_null_rate(p, T, _hns), 4) for p in sorted(_hn)}
T['random_control']['homogeneity_null_rate'] = {
    'bases': sorted(_hrate), 'by_base': {str(p): {'rate': r, 'cells': _hn[p]} for p, r in _hrate.items()}, 'ns': _hns,
    'summary': ('三方向の真の率が同じとき、注（ランダム方向の不均一）が立つ確率（全数・方向ごとの試行 %s）: %s'
                % ('・'.join(str(x) for x in _hns), '・'.join('基底 %g で %.4f' % (p, r) for p, r in _hrate.items()))),
    'note': ('基底は、ランダム方向の腕の土台の V′ の既測の率。**注は帰無でもこの割合で立つ**——注の付いた対比は、帰無の下の揺れでも付きうると読む（採否表 P399・2026-09-19）。'
             '生成のときに `tools/rules_B.py` の `homog_null_rate` で数えた')}
# ---- 品質床の課題の出所の記録（裁定 D146）: `tools/qf_task_B.py --register` が書いた記録から写す（**手で打たない**）。記録が無ければ空（器は実機の測定を拒む） ----
_qreg_p = os.path.join(REPO, *QF_REG_PATH.split('/'))
if os.path.exists(_qreg_p):
    _qb = open(_qreg_p, 'rb').read().replace(b'\r\n', b'\n')
    _qreg = json.loads(_qb.decode('utf-8'))
    assert [c['key'] for c in _qreg['candidates']] == [c['key'] for c in quality['task_candidates']], '出所の記録の候補が正本の候補と違う（--register をやり直す）'
    for _c, _r in zip(quality['task_candidates'], _qreg['candidates']):
        assert (_r['repo'], _r['commit'], [f['name'] for f in _r['files']]) == (_c['repo'], _c['commit'], list(_c['files'])), ('出所の記録の版かファイルが正本と違う', _c['key'])
    assert _qreg['template_sha16'] == hashlib.sha256(json.dumps(quality['presentation'], ensure_ascii=False, sort_keys=True).encode('utf-8')).hexdigest()[:16].upper(), \
        '出所の記録を書いた後に問いの組み立て（presentation）が変わった（--register をやり直す）'
    T['quality_floor']['task_registered'] = {
        'record': QF_REG_PATH, 'record_sha16': hashlib.sha256(_qb).hexdigest()[:16].upper(),
        'template_sha16': _qreg['template_sha16'], 'seed': _qreg['seed'], 'items': _qreg['items'],
        'mmlu_categories': _qreg.get('mmlu_categories'),
        'by_key': {_r['key']: {k: _r[k] for k in ('pool_n', 'fragment_n', 'fragment_sha16', 'dup_choice_rows_pool',
                                                   'dup_choice_rows_fragment', 'answer_dist_fragment')}
                   | {'files': {f['name']: {'bytes': f['bytes'], 'sha16': f['sha256'][:16]} for f in _r['files']}}
                   for _r in _qreg['candidates']},
        'note': ('出所の記録（`tools/qf_task_B.py --register` が候補のデータから書いた）の値を写した（SHA は先頭十六桁）。実機の器は、取ったファイルと組み直した断片をこの値と照らし、'
                 'さらに出所の記録の全長の SHA256 とも照らして（記録の SHA16 を先に正本と照らす）、違えば止まる')}
else:
    T['quality_floor']['task_registered'] = None
# ---- 裁定 D147: 選定（判定の記録から写す・手で打たない） ----
QF_SELECT_REC = 'records/B/qf-selection/qf-select-2026-09-19.json'
_sel = json.load(open(os.path.join(REPO, *QF_SELECT_REC.split('/')), encoding='utf-8'))
QF_CHOSEN = 'jcqa'                                    # 登録者の選定（裁定 D66・D147）
assert _sel['decision']['branch'] == '(i)' and QF_CHOSEN in _sel['decision']['eligible'] and not _sel['problems'], '選定が判定の記録と合わない'
_cells = _sel['cells'][QF_CHOSEN]
T['quality_floor']['selected'] = {
    'key': QF_CHOSEN, 'label': next(c['label'] for c in quality['task_candidates'] if c['key'] == QF_CHOSEN),
    'name': next(c['name'] for c in quality['task_candidates'] if c['key'] == QF_CHOSEN),
    'input_form': _sel['decision']['input_form'], 'branch': _sel['decision']['branch'], 'eligible': list(_sel['decision']['eligible']),
    'decision_record': QF_SELECT_REC, 'decision_record_sha16': hashlib.sha256(open(os.path.join(REPO, *QF_SELECT_REC.split('/')), 'rb').read().replace(b'\r\n', b'\n')).hexdigest()[:16].upper(),
    'fragment_sha16': T['quality_floor']['task_registered']['by_key'][QF_CHOSEN]['fragment_sha16'],
    'base_correct': {a: _cells[a]['correct'] for a in quality['arms']}, 'base_n_ok': {a: _cells[a]['n_ok'] for a in quality['arms']},
    'base_format_fail': {a: _cells[a]['format_fail'] for a in quality['arms']},
    'base_min_applied': quality['base_min'],
    'rule': ('**品質床の課題は甲（JCommonsenseQA）で、前置きを付けて測る**（裁定 D147・2026-09-19 の夕刻・登録者の選定・裁定 D66）。判定の順（裁定 D145）の枝 (i) で、'
             '条件を満たした候補は甲だけだった（判定の記録 `%s`）。下限は `base_min` のまま動かしていない（裁定 D145）。問いは登録した断片（`task_registered`）をそのまま使う') % QF_SELECT_REC}
T['measured']['top_k_stageA_effective'] = {
    'value': TOPK_EFF, 'source': QF_SESSION_REC + ' の topk', 'status': _tk['status'], 'relaunch_log': _tk.get('log'), 'relaunch_log_sha16': _tk.get('log_sha16'),
    'relaunch_vllm': (_tk.get('server_args') or {}).get('vllm'), 'stageA_logs': [{'file': x['file'], 'sha16': x['sha16']} for x in (_tk.get('stageA_logs') or [])],
    'note': ('裁定 D142 の値（裁定 D147）。課題の選定の測定と同じランタイムで立てた vLLM の起動の記録と、Drive に残っていた段階 A の起動の記録の、既定の標本化の値の行から読んだ'
             '（`tools/colab/boot_stageB.py` の読み口・読み方の自己検査つき）。**段階 A の走行器が送った値ではない**（段階 A は top_k を送っていない）')}
s = json.dumps(T, ensure_ascii=False, indent=1) + '\n'
open(OUT, 'w', encoding='utf-8', newline='\n').write(s)
print('[contrasts-B] written %s sha16 %s | m %d | 本走行の腕 %d（場面ごと %s）| 候補 %d 組'
      % (OUT, hashlib.sha256(s.encode('utf-8')).hexdigest()[:16].upper(), sum(F['m'] for F in fam.values()),
         len(main_arms), '・'.join('%s %d' % (sc, len(arms_by_scenario[sc])) for sc in SC), len(LAYERS) * len(COEFS)))
